effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        #define PI 3.14159
        #define TAU 6.28318

        vec3 spunk(vec2 uv)
        {
          vec3 col = vec3(color1.rgb);    // Drop Colour
          // vec3 col = vec3(.55,0.35,1.225);    // Drop Colour
          uv.x += sin(0.2+uv.y*0.8)*xxa;
          uv.y += sin(0.2+uv.x*0.8)*xxx;
          // uv.x += sin(0.2+uv.y*0.8)*0.5;
            uv.x = uv.x*50.0;           // H-Count
            float dx = fract(uv.x);
            uv.x = floor(uv.x);
            float t =  autop? PROGRESS+(acTime*0.5) : PROGRESS * 0.5;
            uv.y *= xxc;             // stretch
            // uv.y *= 0.15;             // stretch
            float o=sin(uv.x*215.4);        // offset
            float s=cos(uv.x*33.1)*0.3 + 0.7;      // speed
            float trail = mix(95.0,35.0,s);     // trail length
            float yv = fract(uv.y + t*s + o) * trail;
            yv = 1.0/yv;
            yv = smoothstep(0.0,1.0,yv*yv);
            yv = sin(yv*PI)*(s*5.0);
            float d2 = sin(dx*PI);
            yv *= d2*d2;
            col = col*yv;
          return col;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iRes = vec2(acScreenSize.x, acScreenSize.y);

        float maxF = max(acScreenSize.x, acScreenSize.y);
        vec2 texelSize = 1.0 / vec2(maxF, maxF);

        vec2 ryu;
        ryu = acScreenNorm; 

        vec2 nxnn;
        nxnn = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        nxnn.y *=acLayerSize.y/acLayerSize.x;
        nxnn /= 10.0;

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y *=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        if(mirrx) { TanRyu.x = 1. - TanRyu.x; }
        if(mirry) { TanRyu.y = 1. - TanRyu.y; }

        /////////////////////////

    	vec4 fragColor;

            float time= autop? PROGRESS+(acTime*0.5) : PROGRESS/10.0;
            // vec2 resolution = TanRyu;
            vec2 resolution = ryu;
            float an = autop? sin(PROGRESS+(acTime*0.5)*64564.8) : sin(PROGRESS*64564.8);

            vec3 ro = vec3( 16.0*cos(an), 0.0, 16.0*sin(an) );
            vec3 ta = vec3( 0.0, 0.0, 0.0 );
            // camera matrix
            vec3 ww = normalize( ta - ro );
            vec3 uu = normalize( cross(ww,vec3(0.0,1.0,0.0) ) );
            vec3 vv = normalize( cross(uu,ww));

            vec3 tot = vec3(0.0);
              // vec2 ppp = ryu;
              vec2 ppp = TanRyu;
              // vec2 ppp = (-iRes.xy + 2.*(fragCoord.xy))/iRes.y;

                vec3 bbk = spunk(ppp.xy);

                // vec2 p = ryu;
                vec2 p = nxnn;
                // vec2 p = (-iRes.xy + 2.0*fragCoord.xy)/iRes.y;

                vec3 rd = normalize( p.x*uu + p.y*vv + 1.5*ww );
                float v = 1.0-abs(p.y);
                vec3 col = bbk*v*2.0 * 3.0; //vec3(v*0.1);
                col = sqrt( col );
               tot += col;

          fragColor = vec4( tot, 0.0 );

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            // resultfinal = (factor * bright) * texColor.a;
            resultfinal = (newLayer(color2, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
